package m8

import "net/http"

func (h *Hub) HandleQuestionsPage(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(pilotQuestionsHTML))
}

const pilotQuestionsHTML = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>研发问题待答清单</title>
<style>body{font:16px system-ui,sans-serif;color:#17263b;background:#f4f6fa;max-width:1080px;margin:24px auto;padding:0 16px}header{display:flex;align-items:center;gap:20px}a{color:#255db5}section,article{background:white;border:1px solid #d8deea;border-radius:10px;padding:18px;margin:14px 0}label{display:block;margin:12px 0}input,textarea,select,button{font:inherit;padding:8px;border:1px solid #aebbd0;border-radius:5px;box-sizing:border-box}input,textarea{width:100%}textarea{min-height:78px}button{cursor:pointer;margin:4px;background:#ecf2fc}button.primary{background:#225cab;color:white}small,.muted{color:#52657e}#status{white-space:pre-wrap}pre{white-space:pre-wrap;overflow-wrap:anywhere}#question-list button{display:block;width:100%;text-align:left;padding:12px}form{border-top:1px solid #d8deea;margin-top:12px;padding-top:8px}[hidden]{display:none!important}.row{display:flex;flex-wrap:wrap;gap:8px}.row label{flex:1;min-width:200px}h1{font-size:24px}h2{font-size:20px}</style>
<header><a href="/console">返回 Console</a><h1>研发问题待答清单</h1></header><p>① 看问题与所等答复　② 集中答复或转派　③ 看重核结果</p><p class="muted">答复到件不等于任务恢复或业务签收；业务变更先留提案，经所有者确认后走新修订。</p><p id="status" role="status"></p>
<div class="row"><button id="refresh">刷新清单</button><button id="next" hidden>下一页</button></div><section><h2>当前获准的问题</h2><div id="question-list"></div></section>
<section id="create-panel" hidden><h2>从原任务提问题</h2><form id="create-form"><label>类型<select id="create-kind"><option value="requirement_unclear">需求不清</option><option value="change">变更</option><option value="technical">技术受阻</option><option value="resource">缺资源</option></select></label><label>标题<input id="create-title" maxlength="180" required></label><label>已知事实与缺口<textarea id="create-fact" maxlength="1200" required></textarea></label><label>要回答的问题<textarea id="create-question" maxlength="1200" required></textarea></label><label>期待的明确答复<textarea id="create-expected" maxlength="1200" required></textarea></label><label>已有证据引用<input id="create-evidence" maxlength="600"></label><label><input id="create-risk" type="checkbox" style="width:auto"> 涉及真实生产动作或安全事项，使用完整档核对</label><button class="primary">登记并送待答清单</button></form></section>
<section id="policy-panel" hidden><h2>所有者一次配置</h2><p>只选已存在的平台用户；飞书未绑定或通道未配置时显示待配置，不按姓名猜收件人。配置只影响新问题，已有问题请明确转派。</p><form id="policy-form"><label>产品经理<select id="policy-pm"></select></label><label>60 分钟未实质答复时提醒谁<select id="policy-leader"></select></label><button>保存新问题的默认人选</button></form></section>
<section id="detail" hidden><h2 id="detail-title"></h2><p id="detail-state"></p><p id="detail-wait"></p><pre id="detail-fact"></pre><pre id="detail-question"></pre><pre id="detail-expected"></pre><p id="detail-delivery"></p><div id="detail-changes"></div>
<form id="answer-form" hidden><h3>集中答复</h3><label>答复<textarea id="answer-body" maxlength="2400" required></textarea></label><label>结论或材料引用<input id="answer-evidence" maxlength="600" required></label><label>本次答复<select id="answer-kind"><option value="substantive">实质答复</option><option value="ack">仅确认收到，继续等待明确答复</option></select></label><label><input id="answer-change" type="checkbox" style="width:auto"> 影响范围、验收或环境约束，留待确认的变更提案</label><button class="primary">答复并回写原问题</button></form>
<form id="assign-form" hidden><h3>转给能处理的人</h3><label>产品协调人<select id="assign-pm"></select></label><label>所等实际责任人<select id="assign-responsible"></select></label><label>超时协调人<select id="assign-leader"></select></label><button>明确转派并撤回旧答复权</button></form>
<div id="manage" hidden><h3>所有者处理</h3><label>处理理由或核对引用<input id="manage-reason" maxlength="600"></label><div class="row"><button id="resolve">问题已闭环</button><button id="cancel">取消本问题</button><button id="reopen">明确重开一轮</button></div><small>问题闭环仍不是任务完成或业务签收；所关联阻塞须先重核通过。</small></div>
<h3>答复与材料历史</h3><div id="answers"></div><button id="older-answers" hidden>更早的答复</button><button id="older-changes" hidden>更早的变更提案</button></section>
<script>
'use strict';
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search),specID=params.get('spec_id')||'',taskID=params.get('task_id')||'';
let renderedID='',formVersion=0;const drafts=new Map();let selected=params.get('question_id')||'',question=null,createContext=null,policy=null,people=[],cursor='',nextCursor='',answerBefore=0,changeBefore=0,loading=false;const pending=new Map();
const kinds={requirement_unclear:'需求不清',change:'变更',technical:'技术受阻',resource:'缺资源'},states={open:'待答',needs_owner:'待明确责任人',awaiting_answer:'等待实质答复',answered_pending_recheck:'答复已到，待执行者重核',resolved:'问题已闭环',cancelled:'已取消',superseded:'已转入新修订'};
const rechecks={waiting:'材料或条件仍缺项',needs_owner:'待明确责任人',ready_to_recheck:'已到件，待重核',rechecking:'重核中',resolved:'重核通过，任务恢复仍由执行者按授权处理',cancelled:'阻塞已取消',needs_reassignment:'待所有者处理指派变化',scope_changed:'原范围或指派已变化，不能以旧答复唤醒新任务',spec_question_no_automatic_task:'仅挂 spec，不自动建任务或唤醒',completed_task_feedback_no_wake:'已完成任务的补充反馈，不自动重开'};
function msg(s){$('status').textContent=s}
function clearPrivate(){question=null;createContext=null;policy=null;formVersion=0;renderedID='';pending.clear();drafts.clear();$('question-list').replaceChildren();for(const id of ['detail','policy-panel','create-panel'])$(id).hidden=true;for(const el of document.querySelectorAll('textarea,input')){if(el.type==='checkbox')el.checked=false;else el.value=''}for(const id of ['detail-title','detail-state','detail-wait','detail-fact','detail-question','detail-expected','detail-delivery','answers','detail-changes'])$(id).replaceChildren()}
async function api(path,options){let r;try{r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options})}catch(_){throw Object.assign(new Error('结果待核对：保留原提交标识，不会自动换一笔重发。'),{unknown:true})}let b={};try{b=await r.json()}catch(_){}if(r.status===401||r.status===403){clearPrivate();throw new Error('当前身份或问题权限已失效，请重新登录或由所有者处理。')}if(!r.ok){if(r.status>=500)throw Object.assign(new Error('结果待核对：请保留内容并用原提交重试。'),{unknown:true});throw Object.assign(new Error(r.status===409?'状态或权限已变化，内容已保留，请刷新核对。':'字段或当前处理条件不符，请核对原问题。'),{conflict:r.status===409})}return b}
function reqID(){return crypto.randomUUID()}
async function write(key,path,data){const comparison={...data};delete comparison.expected_version;const normalized=JSON.stringify(comparison);let p=pending.get(key);if(p&&p.normalized!==normalized){throw new Error('上一笔结果仍待核对，请先核对或以原内容重试；不会自动替换提交。')}if(!p){p={normalized,body:{...data,request_id:reqID()}};pending.set(key,p);p.ready=(async()=>{if(data.operation==='answer'||data.operation==='input'){const bytes=new TextEncoder().encode(JSON.stringify({id:question.id,generation:question.generation,kind:data.answer_kind,body:data.body,evidence:data.evidence_ref,change:data.scope_change}));p.body.event_id=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('')}})()}await p.ready;try{const result=await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p.body)});pending.delete(key);return result}catch(e){if(!e.unknown)pending.delete(key);throw e}}
function opt(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}
async function loadPeople(){if(people.length)return;const id=question?question.spec_id:specID;if(!id)return;const b=await api('/api/console/specs/'+encodeURIComponent(id)+'/question-context');people=b.contacts||[]}
function fillUsers(select,current){select.replaceChildren();opt(select,'','待配置／待分派');for(const p of people){const id=p.id||p.principal_id;if(id)opt(select,id,p.display_name||p.short_name||id)}if(current&&!Array.from(select.options).some(x=>x.value===current))opt(select,current,current);select.value=current||''}
async function ownerOptions(q){if(!q.can_configure_recipients){for(const [id,value] of [['assign-pm',q.pm_user],['assign-leader',q.leader_user]]){const el=$(id);el.replaceChildren();opt(el,value||'',value||'待配置');el.value=value||'';el.disabled=true}const s=$('assign-responsible');s.replaceChildren();for(const id of q.assignment_options||[])opt(s,id,id);s.value=q.responsible_principal||'';return}$('assign-pm').disabled=$('assign-leader').disabled=false;await loadPeople();fillUsers($('assign-pm'),q.pm_user);fillUsers($('assign-leader'),q.leader_user);const s=$('assign-responsible');s.replaceChildren();opt(s,'','待分派');for(const p of people){const id=p.id||p.principal_id;if(id)opt(s,'user:'+id,p.display_name||p.short_name||id)}if(q.task_id){const b=await api('/api/console/task-board?spec_id='+encodeURIComponent(q.spec_id));for(const a of b.task_agents||[]){if(a.id)opt(s,'agent:'+a.id,a.full_name||a.session_name||a.id)}}if(q.responsible_principal&&!Array.from(s.options).some(o=>o.value===q.responsible_principal))opt(s,q.responsible_principal,q.responsible_principal);s.value=q.responsible_principal||''}
function renderQuestion(q,resetForms=false){if(renderedID!==q.id){if(question)drafts.set(question.id,{body:$('answer-body').value,evidence:$('answer-evidence').value,kind:$('answer-kind').value,change:$('answer-change').checked});const d=drafts.get(q.id);$('answer-body').value=d?d.body:'';$('answer-evidence').value=d?d.evidence:'';$('answer-kind').value=d?d.kind:'substantive';$('answer-change').checked=d?d.change:false;$('manage-reason').value='';renderedID=q.id}if(resetForms)formVersion=q.version;question=q;$('detail').hidden=false;$('detail-title').textContent=(kinds[q.kind]||q.kind)+' · '+q.title;$('detail-state').textContent=(states[q.state]||q.state)+'；'+(rechecks[q.recheck_state]||'等待重核记录')+(q.task_status==='in_progress'?'；已由执行者恢复原任务':'');$('detail-wait').textContent='所等人：'+(q.responsible_principal||'待分派')+'；首答截止：'+q.due_at;$('detail-fact').textContent='已知事实：\n'+q.observed_fact;$('detail-question').textContent='问题：\n'+q.question;$('detail-expected').textContent='期待答复：\n'+q.expected_answer;
const delivery=(q.notifications||[]).map(d=>d.state==='pending_config'?'待配置':d.state==='queued'?'待发送':d.state==='dispatching'?'发送结果待核对':d.state==='unknown'?'发送结果未知，待核对（不盲重发）':d.state==='sent'?'接口已接受，未证明本人已读':'已取消');$('detail-delivery').textContent='通知：'+(delivery.join('；')||'等待通知登记');$('answer-form').hidden=!q.can_answer||['resolved','cancelled','superseded'].includes(q.state);$('assign-form').hidden=!q.can_assign||['resolved','cancelled','superseded'].includes(q.state);$('manage').hidden=!q.can_manage;$('reopen').hidden=!q.can_configure_recipients||!['resolved','cancelled'].includes(q.state);}
function renderAnswers(rows){$('answers').replaceChildren();for(const a of rows){const item=document.createElement('article'),h=document.createElement('p'),body=document.createElement('pre');h.textContent=(a.answer_kind==='technical_input'?'技术材料':a.answer_kind==='ack'?'仅收到':'实质答复')+' · 第'+a.generation+'轮 · '+a.actor+' · '+a.created_at;body.textContent=a.body+'\n证据：'+a.evidence_ref;item.append(h,body);$('answers').append(item)}}
function renderChanges(rows){$('detail-changes').replaceChildren();for(const c of rows){const box=document.createElement('article'),p=document.createElement('p');p.textContent='变更提案：'+c.state+(c.reason?'；'+c.reason:'');box.append(p);if(question.can_decide_change&&c.state==='pending'){const reason=document.createElement('input');reason.placeholder='决定理由／证据';const revision=document.createElement('input');revision.type='number';revision.placeholder='已通过原流程生成的新修订号';revision.min='1';const successor=document.createElement('input');successor.placeholder='已定稿时填派生后继 spec ID；原 spec 新修订可留空';const reject=document.createElement('button');reject.textContent='拒绝变更，保留原范围';const confirm=document.createElement('button');confirm.textContent='确认转入已有新修订';reject.onclick=()=>action({operation:'reject_change',change_id:c.id,reason:reason.value});confirm.onclick=()=>action({operation:'confirm_change',change_id:c.id,reason:reason.value,new_revision:Number(revision.value),new_spec_id:successor.value});box.append(reason,reject,successor,revision,confirm)}$('detail-changes').append(box)}}
async function loadDetail(reset=true,which='both'){if(!selected)return;const query=new URLSearchParams();if(!reset&&which==='answers'&&answerBefore)query.set('before',answerBefore);if(!reset&&which==='changes'&&changeBefore)query.set('change_before',changeBefore);const b=await api('/api/console/questions/'+encodeURIComponent(selected)+(query.size?'?'+query:''));renderQuestion(b.question,reset);if(which==='both'||which==='answers'){renderAnswers(b.answers||[]);answerBefore=b.answers_next_before||0}if(which==='both'||which==='changes'){renderChanges(b.changes||[]);changeBefore=b.changes_next_before||0}$('older-answers').hidden=!answerBefore;$('older-changes').hidden=!changeBefore;if(reset&&question.can_assign)await ownerOptions(question)}
async function loadList(reset=true){if(reset)cursor='';const q=new URLSearchParams({limit:'50'});if(specID)q.set('spec_id',specID);if(taskID)q.set('task_id',taskID);if(cursor)q.set('cursor',cursor);const b=await api('/api/console/questions?'+q);$('question-list').replaceChildren();for(const item of b.questions||[]){const button=document.createElement('button');button.textContent=(kinds[item.kind]||item.kind)+' · '+item.title+' · '+(states[item.state]||item.state);button.onclick=()=>{selected=item.id;answerBefore=changeBefore=0;loadDetail().catch(e=>msg(e.message))};$('question-list').append(button)}nextCursor=b.next_cursor||'';$('next').hidden=!nextCursor;if(!(b.questions||[]).length)$('question-list').textContent='当前没有获准待答的问题。'}
async function initCreate(){if(!specID)return;const q=new URLSearchParams();if(taskID)q.set('task_id',taskID);createContext=await api('/api/console/specs/'+encodeURIComponent(specID)+'/question-context'+(q.size?'?'+q:''));$('create-panel').hidden=false;if(createContext.can_configure_policy){await loadPeople();const b=await api('/api/console/specs/'+encodeURIComponent(specID)+'/question-policy');policy=b.policy;fillUsers($('policy-pm'),policy.pm_user);fillUsers($('policy-leader'),policy.leader_user);$('policy-panel').hidden=false}}
async function action(data){if(!question)return;try{const result=await write('question:'+question.id+':'+data.operation,'/api/console/questions/'+encodeURIComponent(question.id),{...data,expected_version:formVersion});msg(result.outcome==='unchanged'?'相同答复已登记，没有重复唤醒。':'已登记到原问题；不表示任务恢复或签收。');await loadDetail();await loadList(false)}catch(e){msg(e.message)}}
$('create-form').onsubmit=async e=>{e.preventDefault();if(!createContext)return;try{const b=await write('create:'+specID+':'+taskID,'/api/console/specs/'+encodeURIComponent(specID)+'/questions',{operation:'create',expected_version:createContext.expected_version,task_id:taskID,kind:$('create-kind').value,title:$('create-title').value,observed_fact:$('create-fact').value,question:$('create-question').value,expected_answer:$('create-expected').value,input_anchors:$('create-evidence').value,production_or_security:$('create-risk').checked});selected=b.question.id;$('create-form').reset();await initCreate();await loadList();await loadDetail();msg('问题已登记；通知送达与答复状态以清单回执为准。')}catch(e){msg(e.message)}};
$('policy-form').onsubmit=async e=>{e.preventDefault();if(!policy)return;try{const b=await write('policy:'+specID,'/api/console/specs/'+encodeURIComponent(specID)+'/question-policy',{operation:'configure_policy',expected_version:policy.version,pm_user:$('policy-pm').value,leader_user:$('policy-leader').value});policy=b.policy;msg('默认人选已保存；已有问题请明确转派。')}catch(e){msg(e.message)}};
$('answer-form').onsubmit=async e=>{e.preventDefault();await action({operation:'answer',answer_kind:$('answer-kind').value,body:$('answer-body').value,evidence_ref:$('answer-evidence').value,scope_change:$('answer-change').checked})};
$('assign-form').onsubmit=async e=>{e.preventDefault();await action({operation:'assign',pm_user:$('assign-pm').value,responsible_principal:$('assign-responsible').value,leader_user:$('assign-leader').value})};
for(const id of ['resolve','cancel','reopen'])$(id).onclick=()=>action({operation:id,reason:$('manage-reason').value});
$('refresh').onclick=async()=>{try{await loadList();if(selected)await loadDetail();await initCreate();msg('已刷新当前授权清单。')}catch(e){msg(e.message)}};
$('next').onclick=()=>{cursor=nextCursor;loadList(false).catch(e=>msg(e.message))};$('older-answers').onclick=()=>loadDetail(false,'answers').catch(e=>msg(e.message));$('older-changes').onclick=()=>loadDetail(false,'changes').catch(e=>msg(e.message));
(async()=>{try{await loadList();await initCreate();if(selected)await loadDetail()}catch(e){msg(e.message)}})();setInterval(async()=>{if(loading||document.hidden)return;loading=true;try{await loadList(false);if(selected){const b=await api('/api/console/questions/'+encodeURIComponent(selected));renderQuestion(b.question)}}catch(e){msg(e.message)}finally{loading=false}},5000);
</script></html>`
